 r=R(cid,rid,label,C[cid]['work'],label.split(' — ',1)[-1],media,continuity,period,population,list(exclusions),text,values,bounds,bases,refs,regime,facts,assumptions,'Reference-led, individually scoped best guess under the 2026-10-17 instruction; admission certainty and numeric assumptions remain explicit.',zero=zero,proxy=proxy or synthetic,alternatives=alternatives)
